const sample = {
  "demo": true,
  "firstName": "Nora",
  "lastName": "Rahman",
  "email": "kai@lumenfreight.example",
  "company": "Lumen Freight",
  "title": "Head of Operations",
  "employees": 42,
  "budget": 8000,
  "source": "referral",
  "utmSource": "linkedin",
  "utmMedium": "cpc",
  "utmCampaign": "ops-audit-q1",
  "event": "Ops Summit"
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const email = String(item.email || '').trim().toLowerCase();
const company = String(item.company || 'Unknown company').trim();
const source = String(item.source || 'unknown').trim().toLowerCase();
const employees = Number(item.employees || item.headcount || 0);
const budget = Number(item.budget || 0);
const title = String(item.title || '').toLowerCase();
const domain = email.includes('@') ? email.split('@')[1] : '';
const freeDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];
const intentSources = ['referral', 'booth', 'demo'];
let score = 15;
const reasons = [];
if (email && !freeDomains.includes(domain)) {
  score += 15;
  reasons.push('work email');
} else if (email) {
  reasons.push('free inbox, keep it in nurture');
}
if (employees >= 50) {
  score += 20;
  reasons.push('headcount at or above 50');
} else if (employees >= 10) {
  score += 10;
  reasons.push('team of 10 or more');
}
if (intentSources.includes(source)) {
  score += 25;
  reasons.push('high-intent source: ' + source);
}
if (budget >= 5000) {
  score += 15;
  reasons.push('budget at or above 5000');
}
if (/(founder|owner|vp|head|director|ceo|cto|cmo)/.test(title)) {
  score += 10;
  reasons.push('buyer title');
}
score = Math.max(0, Math.min(100, score));
let tier = score >= 60 ? 'sql' : score >= 45 ? 'mql' : 'nurture';
const known = Array.isArray(item.knownEmails) ? item.knownEmails.map((value) => String(value).toLowerCase()) : [];
if (email && known.includes(email)) tier = 'duplicate';
const record = {
  email,
  firstName: item.firstName || '',
  lastName: item.lastName || '',
  company,
  title: item.title || '',
  source,
  employees,
  budget,
  score,
  tier,
  reasons: reasons.join('; '),
  dealName: company + ' — ' + tier.toUpperCase(),
  amount: budget,
  stage: tier === 'sql' ? 'appointmentscheduled' : 'qualifiedtobuy',
};
return {
  summary: tier === 'duplicate'
    ? email + ' is already on file. No new HubSpot record is required.'
    : company + ' (' + email + ') scored ' + score + ' and landed in ' + tier + ' for HubSpot.',
  route: tier,
  record,
  slackText: tier.toUpperCase() + ' lead ' + email + ' at ' + company + ' scored ' + score + '. ' + reasons[0],
  actions: [
    { app: 'HubSpot', operation: 'upsert', payload: record },
  ],
};

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'trade-show-badge-to-crm',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
